import { Injectable, inject } from '@angular/core';
import { CanActivate, Router } from '@angular/router';
import { LocalStorageService } from '../services/localStorage/local-storage.service';

/**
 * Guard para proteger rutas de autenticación (login, register)
 * Redirige a usuarios ya logueados al panel principal
 */
@Injectable({
  providedIn: 'root'
})
export class AuthGuard implements CanActivate {
  private localStorageService = inject(LocalStorageService);
  private router = inject(Router);

  /**
   * Verifica si el usuario está logueado
   * @returns boolean - true si puede acceder, false si debe ser redirigido
   */
  canActivate(): boolean {
    // Verificar si el usuario está logueado usando el servicio existente
    if (this.localStorageService.isUserLogged()) {
      // Usuario ya está logueado, redirigir al panel principal
      this.router.navigate(['/main']);
      return false; // Bloquear acceso a login/registro
    }

    // Usuario no está logueado, permitir acceso a login/registro
    return true;
  }
}

/**
 * Guard para rutas que requieren autenticación
 * Redirige a login si el usuario no está logueado
 */
@Injectable({
  providedIn: 'root'
})
export class AuthenticatedGuard implements CanActivate {
  private localStorageService = inject(LocalStorageService);
  private router = inject(Router);

  /**
   * Verifica si el usuario está logueado
   * @returns boolean - true si puede acceder, false si debe ser redirigido a login
   */
  canActivate(): boolean {
    if (!this.localStorageService.isUserLogged()) {
      // Usuario no está logueado, redirigir a login
      this.router.navigate(['/auth/login']);
      return false;
    }

    // Usuario está logueado, permitir acceso
    return true;
  }
}

/**
 * Guard para rutas que requieren rol de administrador
 * Permite solo usuarios con rol de admin (general o de usuarios)
 */
@Injectable({
  providedIn: 'root'
})
export class AdminGuard implements CanActivate {
  private localStorageService = inject(LocalStorageService);
  private router = inject(Router);

  /**
   * Verifica si el usuario es administrador
   * @returns boolean - true si es admin, false si debe ser redirigido
   */
  canActivate(): boolean {
    if (!this.localStorageService.isUserLogged()) {
      // Usuario no está logueado, redirigir a login
      this.router.navigate(['/auth/login']);
      return false;
    }

    const userData = this.localStorageService.getUser();
    const roles = userData?.roles || [];

    // Verificar si tiene rol de administrador (admin general o de usuarios)
    const isAdmin = roles.some(role =>
      role.toLowerCase().includes('admin') ||
      role.toLowerCase().includes('administrador')
    );

    // También verificar si es el admin principal por email
    const isMainAdmin = this.localStorageService.esAdmin();

    if (!isAdmin && !isMainAdmin) {
      // Usuario no es administrador, redirigir al panel principal
      this.router.navigate(['/main']);
      return false;
    }

    // Usuario es administrador, permitir acceso
    return true;
  }
}